		"title": "내가 예전부터 정말 좋아했던 소꿉친구에게 1개월의 금욕을 시켜 그녀가 없는 동안 고생한 달콤하고도 애틋한 3일간 아케사토츠무기",
		"story": "혜택, 세트 상품 정보 오토나의 썸머 캠페인 2025 8월 5일 아침 10시부터 9월 12일 아침 10시까지 기간 중 S1과 무디스, 마돈나 등 인기 메이커의 대상 상품이 40% 할인!! 또한 기간 중 대상 상품을 구입한 80000명에게는 캠페인걸 엽서(전6종)를 랜덤으로 1장 증정!! ※행사 종료 후, 발송까지 시간이 걸리는 경우, 주문을 분할해 드리는 경우가 있습니다. 미리 양해 부탁드립니다. 혜택이 포함된 상품, 세트 상품에 대해 「아카리 츠무기」의 순애 NTR 드라마가 등장. 일상이 있을 법한 리얼을 고집한 어느 상황 공감 작품. 줄곧 소꿉친구를 한결같이 생각했던 '츠무기'. 바람을 피우고 있나요? 그녀를 믿지 못하고 여성불신이 되는 '료스케'. 그런 '료스케'에게 전하지 못한 마음을 고백하는 '츠무기'. 여성을 믿지 못하는 '료스케'에게 '츠무기'는 1개월간의 금욕을 약속한다. 약속을 지킨 「츠무기」와「료스케」의 3일간 한정의 동거생활이 스타트. 지금까지의 쌓여있던 생각과 성욕이 폭발해 몇번이고 몇번이고 몸과 마음을 거듭하는 2명. 이야! 더이상 떠나고 싶지 않아! 언니보다 더 세게 안아줘! 갖고 싶어! 료스케(亮介)의 친친을 원해! 꽂혀! 꽂혀 더 세게 찌르고 있어!",
