		"title": "손이 닿지 않는다며 포기하고 있던 아르바이트생의 너무 아름다운 선배는 취하면 키스마로... 진한 벨로키스 유혹과 배덕바람 성교는 평생 잊지 못할 달콤한 꿀맛이 났다. 카에데카렌",
		"story": "혜택, 세트 상품 정보 오토나의 썸머 캠페인 2025 8월 5일 아침 10시부터 9월 12일 아침 10시까지 기간 중 S1과 무디스, 마돈나 등 인기 메이커의 대상 상품이 40% 할인!! 또한 기간 중 대상 상품을 구입한 80000명에게는 캠페인걸 엽서(전6종)를 랜덤으로 1장 증정!! ※행사 종료 후, 발송까지 시간이 걸리는 경우, 주문을 분할해 드리는 경우가 있습니다. 미리 양해 부탁드립니다. 혜택이 포함된 상품, 세트 상품에 대해 내가 일하는 곳에는 믿을 수 없을 정도로 예쁜 여자가 있다. 어쩌면 다들 경험이 있을지도 모른다. 매우 아름답고 귀여운 사람이 곁에 있다. 그렇지만, 자신과는 어울리지 않는다고, 사양하고, 경원하고, 선을 긋고, 꿈같은 이야기로 만들어 버리는 것. 나도 그랬어. 여자 경험이 없는 나는, 최근에 여자친구가 생긴지 얼마 되지 않았지만 선배만큼 예쁘지도 않고, 귀엽지도 않다. 나에게 어울리는 신분에 맞는 상대. 단지, 그런 상대에게조차, 한 발 내딛는 것도 사양하기 쉽고 야한 것은 물론, 그에 가까운 일도, 아직 경험해 본 적이 없다. 그런 생각을 하며 오늘도 방학의 시간. 문득 선배를 바라본다. 이런 예쁜 사람은 어떤 남자와 어떤 어른스러운 일을 할까. 요염한 입술을 바라보고 있는데 선배가 그 요염한 입술을 열며 말했다. '야, 일 끝났으니까 마시지 않을래?' 이것이 기적적이고 자극적인 키스 이야기의 시작이었다.",
