		"story": "특전·세트 상품 정보 대형 가슴 캠페인 2026년 7월 3일 오전 10시부터 7월 27일 오전 10시까지 기간 동안, 대상 상품이 30% 할인! 게다가, 대상 Blu‑ray 디스크 온디맨드 상품은 세금 포함 1,540엔!! ※ 캠페인 종료 후 배송까지 시간이 지연될 경우, 주문을 분할 처리할 수 있습니다. 미리 양해 부탁드립니다. 특전이 포함된 상품·세트 상품에 대하여 그날, 출근하자마자 내 책상에 전화가 울렸다. “엥… 사지가 퇴직 대행으로 날아갔어? 네, 알겠습니다…」그것은 무단 결근 중이던 신입 사원 사지가 퇴직 대행을 이용해 회사를 그만두었다는 내용이었다. 요즘 젊은이들은 스스로 퇴직한다는 말조차 못 하는 건가 싶어 화가 났던 내게, 좌자에게서 퇴직서가 도착했는데, 봉투 안에 또 한 장, “네 아내 최고였어”라며 아내의 불륜을 암시하는 듯한 말이 적혀 있었다…",
