		"story": "임신 중인 언니로부터 검사 입원 중 매형 요시오의 보살핌을 부탁받은 나오. 그러다 우연히 요시오가 낯선 여자와 걷는 모습을 목격하고.누나가 힘들 때 부정한 짓을 하려는 요시오에게 곤두서는 것이었다.「여자라면 누구라도 괜찮아?」 경멸하는 시선을 보내는 나오에게 매도당할 정도로 흥분해 버린 요시오는, 그녀를 입막음으로●하는 것이었다.죽여버리고 싶을 정도의 억울함을 맛보며 욕을 먹고 자꾸 오징어를 당하는 나오는.특전 및 세트 상품 정보 GW 대감사제 2023! 4월 21일 아침 10시부터 5월 12일 아침 10시까지의 기간 동안, 대상 상품이 최대 35% 할인!! 또한, 기간 중에 대상 상품을 구입하신 분 중에서 40000명에게 캠페인 걸의 생사진(총 5종)을 랜덤으로 1매 증정!!※ 캠페인 기간 중이라도 혜택은 없어지는 대로 배포가 종료됩니다.※ 캠페인 종료 후, 발송까지 시간이 걸리는 경우, 주문이 분할될 수 있습니다.미리 양해 부탁드립니다.",
