		"story": "지방으로 출장간 여자 상사와 부하. 저녁 무렵까지 돌아갈 수 있으면 늦지 않았을 텐데, 예상보다 빨리 태풍이 상륙. 탈 예정이었던 항공편이 운휴가 되어 버려서 서둘러 묵을 수 있는 장소를 찾았지만 발견된 것은 1실. 회사의 동정부하고 절대로 [없다]고는 생각했지만... 당신 동정이지?w' 이 한마디로 불탄 남자 부하는 '리아'에 눈이 무너져 내린다! 젊은 여자 상사에게 욕망을 억제할 수 없는 남성 부하... 눈사태 SEX!!",
