		"story": "혜택, 세트 상품 정보 연말 신춘 SUPER 캠페인 12월 12일 12시부터 1월 23일 아침 10시까지 기간 중, S1이나 무디스, 마돈나 등 인기 메이커 대상 상품이 40% 할인! ※행사 종료 후, 발송까지 시간이 걸리는 경우, 주문을 분할해 드리는 경우가 있습니다. 미리 양해 부탁드립니다. 혜택이 포함된 상품, 세트 상품에 대해 깨달았을 때는 이미 늦었다. 어젯밤 아야카와 놀았다는 사실을 깨달았어. 토요일 아침 거의 벌거벗은 상태로 눈을 뜨고 옆에 여사친이 있다. 어젯밤 기억이 하나도 없어, 말 놓치잖아. 하지만 이 상황은 술김에 해버린 것일 것이다. 역시, 좋지 않은 일인 것을 알고 있다. 그런데 한 번 더 하고 싶다, 그렇게 성욕이 나한테 얘기해. 어제의 기억이 기억나지 않는 것이 분하다. 그래서 오늘 그걸 덮어쓰고 싶어! 이제 이참에 해도 되겠다…. 섞이는 피부는 남녀의 우정을 넘어간다~",
