		"story": "이 봄부터 배속된 부서에서는 착각 중년 상사의 일상적 성희롱이 횡행하고 있었다… 어느 날 그 상사에게 출장 동행을 명령받는다.그것이 비극의 시작이었다... 음~ 참을 수 없어, 이 천연 롤리보인!출장지에서 진흙●만들려 겨냥된 젊고 풍만한 H컵! 주물러지고 빨려들어가 젊은 젖가슴에 덤벼드는 중년의 강욕.기색나쁘게 최대팽창해 악취를 발하는 오치●뽀로 몇번이나 격돌되어 굴욕의 절정을 반복하는 절륜 NTR! 프리플리의 신규졸 거유를 주물러 몇번이나 토정을 받는다.빵스토로 찌든 방순망즙도 조임도 파이즐리도 모두 최고야... 오늘밤은 이 거유로 무한 사정해 줄 테니까...",
