		"story": "특전·세트 상품 정보 FANZA 7주년 캠페인 덕분에 FANZA가 7주년을 맞이했습니다! 7주년 캠페인으로 인기 제조사의 최신 예약 상품을 포함한 대상 상품을 최대 40% 할인!! ※ 캠페인 종료 후 배송까지 시간이 지연될 경우, 주문을 나누어 진행할 수 있습니다. 미리 양해 부탁드립니다. 특전이 포함된 상품·세트 상품에 대하여 【가해자 A의 증언 범행 시각 23시 현장 회사 안] 아니, 코히나타가 저렇게 가슴을 늘어뜨리고 배회하는 건 별로죠. 공격당하고 싶지 않다면, 저렇게 꽉 끼는 니트를 입지 말라는 얘기죠. 큰 가슴이 ‘아프다— 찢어 주세요’라고 말하는 거잖아요 ㅋㅋ 그래서 두 사람만 남았을 때, 가슴을 힘껏 풀어줬어요 ㅋㅋ 그게 전부예요. 내가 잘못했나요? 【가해자 B·C의 증언 범행 시각 26시 현장 가해자 집] 사무실 안에 가슴을 내민 코히나타 씨가 있었어요. 공격당했을 때도 울고 있었죠. 하지만 그건 가슴을 드러내는 이야기가 아니지 않나요? 웃음, 또 공격해 주길 바라는 건가 싶잖아요. 보통이야. 그렇지? 맞아, 그래서 우리, 데려다 줬어. 그 뒤로는 완전 난리 났지. 어, 죄책감이 없었다고? 어, 애초에 죄인가요? 웃으며 저런 복장을 하고 ‘도와줘’라고 말한 코히나타 씨가 가해자잖아, 웃음【가해자 D의 증언 범행 시각 28시 현장 가해자 집] 이렇게 될 일은, 코히나타 군을 채용한 순간부터 이미 정해져 있었어요. 예전부터 의지받아 왔고, 의지받을 수 있게 부드럽게 대해 줬잖아. 가장 먼저 도와달라고 했죠. 하지만 코히나타 군, 그건 별로 좋지 않은 것 같아. 그렇게 음란한 옷차림 그대로 우리 집에 오는 건 말이야. 공격당한 채로 오는 건 이해하지만, 옷 갈아입자. 가슴을 다 드러내고 말이야. 이번엔 부드럽게 안아주고 싶은 걸까? 그렇게 생각하지 않나요. 오히려 공격하지 않으면 신사가 아니잖아요 ㅋㅋ 뭔가 예민해진 건가, 가슴을 흔들며 결국 기뻐했어요 ㅋㅋ 나, 나쁘지 않지, 네, 그러니까 이제 그만해도 되겠죠?",
