		"story": "심야에 울린 갑작스러운 전화. '막차 놓쳐서, 지금부터 가도 될까?' 그녀의 여동생 '미유'의 부탁에 역시 맛이 없다고 생각하면서도 억지로 묵게 된다. 집에 와서, 목욕을 빌리고, 소파에서 휴식을 취하는 그녀. 실내복에서 긴장을 풀고 있는 풍만한 골짜기에 무심코 눈이 가면 '제 젖가슴 못 봤어요?' 혹시 흥분했어? 일부러 보여준 거야? 유혹하는 것은 아닌 것 같지만 분명히 야한 분위기. 게다가 부드러워 보이는 입술을 장난스럽게 다가와 키스를 부르는 마네킹에 나의 이성은 붕괴했다!! '언니한테는 말하지 않으니까?' 멍들고 작은 악마로 분위기 좋은 그녀의 여동생을 오늘은 엉망으로 만들거야!!",
