		"title": "",
		"story": "【기적의 더 원석 이노우에 모모가 MOODYZ 대인기 시리즈에 드디어 출연! … 안 돼, 안 된다고 생각할 정도로 음탕하게 교차하는 배덕적인 쾌감! 학교에서 가장 귀여운 모모에게 고백받은 담임 선생님인 나. 나는 아내가 있는데… **로서 그를 막아야 하는데…. 작고 동그란 눈으로 바라보며, 부끄러워하면서도 억센 유혹을 하는 모모에게 이성은 무너지고… 털도 나지 않은 깨끗한 여자, 같은 반 친구들보다 훨씬 순진한 모모에게 흥분이 가시지 않아, 아내도 **라는 입장도 잊고 몸을 겹쳤다… “선생님… 오늘은 아내를 잊어줬으면 해요…”, “선생님… 오늘은 마음에 드는 곳에 내보내 주세요” 내 자지에 몸이 경련을 일으키며 여러 번 절정에 이르는 모모가 너무 기분이 좋아서… 미안해요….",
