		"story": "평소에 진지하고 조용한 내성적인 성격의 모모는, 어머니의 재혼으로 생긴 아버지에게 절도 습관이 들통난다. 일상적인 자극 부족으로 절도에 손을 대게 된 모모에게, 아버지는 리모트 바이브로 훈련을 시작한다. 게다가, 최음제로 감도를 높인 모모의 몸은 집 안 곳곳에서 리모바이 경련을 일으킨다. 하지만, 절정에 이를 것 같으면 멈추려는 순간을 멈춘다. “아빠, 오르가즘을 느끼게 해 주세요…” 참을 수 없게 된 모모는 간청 절정. 극한까지 초조하게 만든 민감한 순간 멈춤 이키마○코는, 아버지의 대형 침술기로 실금 이키를 연속으로!",
