		"title": "진지하고 말이 없는 어릴 적 친구가 부끄러워하며 유혹적인 팬티가 보이는 장면으로 얼굴이 빨개지는 사랑. 내 번쩍이는 시선에 흥분해서 물에 젖은 듯한 비치! 이노우에 모모",
		"story": "‘남자들은 다 팬티를 좋아하잖아!’ 부끄러움을 타는 모모짱이 살짝 대담하게 팬티를 보여주며 유혹! 좋아하는 어린 시절 친구에게 마음을 돌리길 바라며 머뭇거리며 도발했더니… 옷감을 뚫을 정도로 강렬한 시선에 흥분과 수치심이 뒤섞여 부끄러운 얼룩이 흐르고 말았다! ‘잠깐… 안 젖었잖아’라며 볼을 붉히고 작은 떨림 섞인 목소리로 변명하는 모습에 가슴이 두근두근! 몸부림! 초러블리! 게다가 통통하고 탄력 있는 여성기가 팬티에 파고 들어가서 깔끔한 마스지(가슴)가 그대로 드러나요! 참을 수 없는 발정 남자는 큰 엉덩이에 얼굴을 대고 푹푹 눌러서 천을 통해 구강성교! 흘러나오는 맨주스를 핥아 빨아먹고! 그리고 힘으로 휘두르며 끼워 넣고! 기다리던 섹스를 원하고 마○코가 바로 오르며 경련! 그 뒤로 여러 번 절정에 이르는 변태 소녀와 청춘 러브가 폭주!",
