		"name": "SNOS-183",
		"title": "최강 히로인과 함께 막차를 놓치고 호텔에 묵고 아침까지 하고 싶어! 세토 카나",
		"story": "거리감이 너무 가까워! 너무 귀여워! 걱정 없는 미소와 천재적인 작은 악마 같은 알바 후배 '카나'. 그런 그녀와 퇴근 후, 뜻밖에 함께 막차를 놓치고 말았다…. ‘어떻게 할까?’라며 위를 올려다보는 눈빛을 받으며, 어쩔 수 없이 묵은 호텔은 같은 방이었다. 밀실 × 미인 × 도발 = 이성 붕괴. 샤워실에서 비치는 최고의 누드 실루엣, 목욕 후 뜨거워진 피부, 달콤한 향기. 압도적인 외모와 몸매 앞에서, 내 사타구니는 이미 한계 돌파. 그걸 재미있게 여기듯, 그녀는 순수하게 뒤를 쫓아온다. “어, 선배 진짜 딱딱하네(웃음) 혹시 나를 공격하고 싶어? … 공격한다면 좀 더 강압적으로 해줘?” 완전히 시험당하고 있어! 알고 있음에도 불구하고, 이제는 저항할 수가 없어……!! 에이, 어쩔 수 없지! 그리고… 여유롭던 그녀가 쾌감에 빠져 암컷으로 변하는 순간. 침대에서 쾌감을 탐닉하고, 샤워실에서는 몸을 붙이며 포옹하고, 아침에 일어나 다시 서로를 갈구한다. “선배, 더 하고 싶어… 한 번 더 할래??” 사랑스러움이 넘치고, 최고로 귀여우면서도 확실히 섹시해. 이런 후배를 좋아하게 될 리가 없잖아.",
