		"story": "2025년 6월 17일 발매의 상품입니다. 두바퀴 이상의 나이 차이혼한 레이나는 아무런 불편도 없는 생활에 만족하고 있을 생각이었지만, 단지 유일하게, 남편과의 섹스리스 생활에는 불만이 쌓여 있었다…. 새장 속에 갇혀 있는 듯한 감각…섹스하고 싶은데 할 수 없는 상황에 몸은 뇌내 호르몬의 분비를 요구하고 있었다. 한계에 다다른 아내는 남편의 부하를 엉덩굴 페로몬으로 끌어당겨 아나루를 통째로 유혹해 남편 이외의 진보로 행복감을 얻는다… 유부녀 아나루의 불륜은 시작… ※ 해당 상품은 2025/05/22 이후 예약 주문 취소가 불가능합니다. ■ 디스크 온디맨드 상품에 대해, 이 상품은 주문을 받은 후에 온디맨드(BD-R)로 제조되고 있습니다. 자세한 내용은 이 주문형 상품이란 제조사의 허락을 받아 복사 작성된 상품입니다. 따라서 패키지나 디스크 라벨은 일반 상품과는 다릅니다. 주문형 상품은 이용 중인 재생 기기의 환경에 따라 재생되지 않을 수 있습니다. 재생이 가능한지 어떤지는, 이용기기의 제조사 사이트에서 확인하시기 바랍니다. (동작확인 정보 등) ※PlayStation등의 게임기나 PC로의 재생은 동작보증외입니다. 상품 페이지에 표시되어 있는 패키지 이미지 등은 일반 상품의 이미지입니다. 주문형 상품의 이미지가 아닙니다. 디스크 온 디맨드 상품에서는 상품 코멘트, 패키지에 기재되어 있는 특전 DVD 등은 포함되어 있지 않습니다. ■ 주문·발송에 대해서 본 제품은 유패킷 발송입니다. 시간 지정 등은 받을 수 없으므로 양해 바랍니다. 주문 후 도착까지 1주일 정도 소요될 수 있습니다. ※ 디스크 온디맨드 상품을 여러 개 동시에 주문하신 경우는 일본우편 일반배송입니다. ※ 여러 주문이 동시에 발송될 경우, 일본 우편의 통상 배송으로 동봉 발송이 될 수 있습니다. 주문 확정 후 3시간 이후에는 고객 사정으로 인한 취소가 불가능합니다.",
