		"title": "손맛에 들인 귀여운 의녀(레이나)…남자친구와 너무 섹*를 해서 괘씸해서 성감대를 들여다보고 7일간 계속 오징어로 만들기로 했다. 미야시타레나",
		"story": "혜택, 세트 상품 정보 연말 신춘 SUPER 캠페인 12월 12일 12시부터 1월 23일 아침 10시까지 기간 중, S1이나 무디스, 마돈나 등 인기 메이커 대상 상품이 40% 할인! ※행사 종료 후, 발송까지 시간이 걸리는 경우, 주문을 분할해 드리는 경우가 있습니다. 미리 양해 부탁드립니다. 혜택이 포함된 상품, 세트 상품에 대해 【귀여운 의녀의 삐삐 바디 성감대를 살리고 싶다】재혼해서 생긴 의녀 레이나의 성장을 계속 지켜봐 왔다. 하지만 요즘 어디 말뼈인지 모르는 남자에게 뺏기고 있다. 용서할 수 없어, 레이나(玲奈)의 기분 좋은 장소는 다 알아. 빙빙 젖꼭지 코네쿠리 핥기, 스렌다크빌레에 빨아먹고, 아름다운 엉덩이를 쓰다듬고 주물러서 야루! 땀흘리면 바닷바람 놀이를 반복해줘서 기뻐. 장인어른 진포로 꽉 조이고 생기발랄하네. 절대로 떠나지 못하도록 확실히 교육시켜줄게.",
