		"title": "미인에다 제대로 빈틈도 있는 그런 기상 캐스터는 국내 성희롱적 표적이 너무 되어 거의 섹* 워커로. 쿠라키하나",
		"story": "세상에는 반드시 겉과 속이 있다. 반짝반짝 빛나는 세계에는 반드시 걸쭉하고 탁한 어른의 세계가 있다. 임기 탤런트가 되기 위해 아침의 기상캐스터로 발탁된 쿠라키는 인기 여배우 수준의 비주얼로 게다가 큰 키에 날씬하게 자란 손발과 프로포션 발군, 장래 유망. 단지 그런 그녀는 프로그램 내외에서 가슴을 드러내기도 하고 펀치를 날리기도 하고 확실히 빈틈이 있다. 그런 가드 헐렁한 그녀에게 국내에서 절대적인 권력을 쥔 거물 진행자 마의 손이 살며시 다가왔다. 처음 시작된 것은, 다리나 엉덩이를 만지는 아무렇지도 않은 성희롱. 우연인 줄 알았는데 드디어 확신이 되는 일이 분장실에서 화가 났다. 방을 둘이서만 빼앗기고 위협당해서 몸을 상납하는 하메에게…. 쪼잔한 치●뽀가 아직 몸에 남는다. 성희롱은 한층 더 과격해져, 스타일리스트와 그루가 되어 프로그램중에 장난감을 어소코에 짜여져 리모트 바이브 플레이를 실시하는 상황. 안 된다는 느낌이 들어, 목소리가 막히면서도 예보 원고를 읽고, 다리는 사각사각, 사각사각 대량 쾌락을 누설. 이제 여기서부터는 분별이 없고, 프로그램의 성 매춘부로서 힘쓰는 매일. 유명해져서 사람들이 주목해서 반짝반짝 하고 싶었을 뿐인데… 어디서 발을 헛디뎠을까. 그녀의 마음은 망가져 버리고, 몇만명의 안방의 사람으로부터 보여지면서 온에어중도 기분좋아지고 있는 수치 쾌감에 늪에 빠져 버리고, 게다가 느낄수록 시청률도 오르고, 더 갖고 싶어져 완전히 세뇌된 미인 기상 캐스터. 이것은 이제 완전한 섹스 워커입니다.",
