		"story": "특전·세트 상품 정보 오토나의 썸머 캠페인 2026S1과 무디즈, 마돈나 등 인기 제조사의 최신 예약 상품을 포함한 대상 상품이 40% 할인!! ※ 캠페인 종료 후 배송까지 시간이 지연될 경우, 주문을 분할 처리할 수 있습니다. 미리 양해 부탁드립니다. 특전이 포함된 상품·세트 상품에 대하여 【그녀의 절친 유카와 여러 차례 금지된 생일 삽입, 땀에 젖은 중출…】 나와 그녀, 유카는 중학교 시절부터 절친한 친구. 시간만 있으면 세 명이서 늘 같이 놀았다. 그녀가 없을 때, 유카가 감기에 걸린 나를 돌보러 와줬다. 오랫동안 숨겨왔던 감정… 두 사람만의 시간… 동경하던 그녀의 절친의 유두·자궁·항문! 불타는 듯이 여러 번, 또 여러 번 삽입한다! 침도 정자도 체액도 섞여서, 계속해서 점막을 엮어가는 베로키스 중출. 절친 사이이기에 멈출 수 없는 바람 섹스가 너무 기분 좋고…",
