		"title": "죽을 정도로 싫어하는 성희롱 상사에게 약점 잡혀 출장 같은 방 NTR 아침햇살이 두 번 올라가도 끈적끈적한 절륜 점착 피스톤 속에서 10발에 굴복한 나... 신아리나",
		"story": "'남자친구도 있는 부하에게 손을 댈 리가 없잖아' 전부 거짓말이었다. 성희롱, 모라하라 상습 부장과의 출장. 계획된 같은 방. 술에 취한 나는, 의식이 없는 채로 수간레×프되어 중출까지…. 그 동영상을 협박 재료로 거역할 수 없게 된 나는 남자친구에게 도움도 요청하지 못하고 2박 3일의 긴 시간 동안 몇 번이나 몇 번이나 범●당해서 몇 번이나 계속 중출되었다. 팬스트 너머의 발을 베로베로 핥아져, 요다레 투성이의 키스를 요구받고. 냄새나는 치○뽀도 억지로 물게 되었다... 선 채로 바이브로 혼나고, 생각나는 것도 부끄러운 가랑이 차림으로 오징어를 당하고... 천천히, 끈적끈적하게 질속을 두드리는 것 같은 점착 피스톤과 짐승과 같은 거친 피스톤을 나누어 사용해 공들여 오마○이를 파여, 분한데도 있어 버린다. 도망갈 곳이 없는 밀실에서 정자가 넘쳐날 정도로 자궁에 쏠려 나는...",
