		"story": "【청순파 미소녀·순백 아야나가의 첫! 본격 NTR작품】같은 입시학원에서 만나 교제한 아야나가는, 재수해 버린 복보다 한발 먼저 상경하게 되었다. 대**활을 즐기고 있어, 이번에 테니서의 [신환컴파]에 참가한다고 한다. 하지만 술에 약한 아야나가가 모르는 남자들과 마신다니.. 너무 걱정된다. 안심시키기 위해서 보내져 온 동영상에는 아니나 다를까 웨이계 인싸들이 나오고 게다가…가볍게 바디 터치되면서도 거부하지 않고 웃는 얼굴로 즐기는 아야나가의 모습이. 설마………………. 얼굴만 보고 노는 것밖에 생각하지 않는 원숭이 집단과 같은 흐름으로 숙식을 하는 이유가 없지? 술김에 만지고 물렁거려 마음대로 가슴을 주무르고 경박한 치○포를 상대로 스스로 헐떡이며 허리를 흔들고… 말도 안 되지만… 싫은 망상이 머리에서 떠나지 않는다.",
