		"story": "아내에게는 어릴 적부터 친한 친구가 있다. 보아하니 임신 준비 중이라는 사실을 절친에게도 상담하고 있는 모양이다. 배란일을 재서 정자를 질에 주입하는 타이밍 요법이 있다고 하니, 차라리 배란일까지 금욕하기로 했다. 그리고 아내의 배란 전날, 절친의 배려로 정성을 다한 요리를 대접받고, 금욕도 겸한 미인 아내의 절친에게 사타구니가 반응해버려, 큰일이 났다… 아내가 잠들고 나서 나도 진정하려는 순간, 아내의 절친이 “아까 정액 나왔지??”, “정액을 나오게 하려다 멈추면 정자가 많이 모인대”, “한 번 시험해볼래?” 라는 유혹에 넘어가 버린 나. 어? 혹시 핥는 거야?? ‘펠라라면 바람 피우는 게 아니겠지’라며 귀두부터 고환, 항문까지 아래를 기어다니듯이 쭉쭉 핥아대고, 절정 직전에서 멈추는 행동을 반복해 터질 듯한 순간! 딥스루트로 참지 못하고 대량 사정… 미안, 아기를 만들기 위해 모아두던 게 엉망이 됐어. 그리고 그 토네이도처럼 따라가며 근원부터 귀두까지 기어다니는 절친의 구강 기술이 잊혀지지 않아. 금욕은 하지만 전날 참지 못하고 주문해버리고, 그대로 상황이 악화돼 섹스까지… 금욕으로 민감한 조루가 ● 포니 최고의 페라치오, 그리고 불륜의 배덕감에 빠진 나는 이대로 성의 나락에 빠져버릴까….",
