		"story": "특전, 세트 상품 정보 AV 사랑 캠페인 20251월 24일 15시부터 2월 14일 10시까지 기간 중, 대상 상품이 35% 할인! 또한 대상 Blu-ray 디스크 온디맨드 상품이 세금 포함 1540엔! 혜택이 포함된 상품, 세트 상품에 대해 모판●구동●노리●역 근처의 영업소에 근무하는 보험 여자 사원의 신인 M씨. 어떻게든 계약을 하고 싶다···. 성적이 부진하여 어느 한 집의 허름한 저택에 방문한다. 절대 계약해주지 않을 것 같은 무뚝뚝함과 옷차림, 밑져야 본전으로 영업하다 보면 '됐어, 들어갈게' 그 한마디에 안심한 것도 잠시, 억지로 이상한 약을 먹고 몸을 만지작거리게 된다. 머리가 화끈거리고 조금만 만져도 민감한 반응. 그리고 일반 섹스보다 수백 배나 기분이 좋다. 지금까지 이런 적이 없었는데 마음대로 조수가 철렁철렁 나오고 비쿤비쿤 경련. 게다가 지금까지의 러브 러브 에이치 같은 것보다 더 쾌락을 맛볼 수 있는 아저씨의 농후 절륜치●뽀. 부감으로 보면, 이런 건 내가 아니야... 하지만 한 번 최음약이라는 마력에 걸려 메스꺼움●코로 내미는 아헤어헤어 절정에서 뇌즙, 에로즙 멈추지 않는다. 살면서 이렇게 기분 좋은 일이 있었어. 고집에 약해 세상을 잘 모르는 순진한 20대 여자는 키메섹에 빠져 망가져 가는 것이었다.",
