		"story": "[당신을 매우 좋아합니다.]지금까지도. 앞으로도.남편을 매우 좋아하는데 배신하고 싶지 않은데, 그래도 저지르고 만 '원하지 않는 불륜 SEX'. 남편의 조루, 전 남자친구로부터의 연락, 모든 타이밍이 교차하여 태어난 비일상적인 하룻밤.남편에게는 보여줄 수 없었던 변태 플레이의 여러가지…성 궁합이 뛰어난 전 남자친구에게 홀려 땀띠 눈물로 시트를 적시는 오늘날의 지저분한 성교.사랑하기 때문에 태어난 신개념 NTR 작품.특전 및 세트 상품 정보 GW 대감사제 2023! 4월 21일 아침 10시부터 5월 12일 아침 10시까지의 기간 동안, 대상 상품이 최대 35% 할인!! 또한, 기간 중에 대상 상품을 구입하신 분 중에서 40000명에게 캠페인 걸의 생사진(총 5종)을 랜덤으로 1매 증정!!※ 캠페인 기간 중이라도 혜택은 없어지는 대로 배포가 종료됩니다.※ 캠페인 종료 후, 발송까지 시간이 걸리는 경우, 주문이 분할될 수 있습니다.미리 양해 부탁드립니다.",
