		"story": "사건은 돌연 일어났다. 회사에서 술자리에서 돌아오는 길에 동기인 미루 양을 간호하다가 갑자기 키스를 했다. 가슴이 철렁했지만 아직 나는 냉정했다. 막차를 놓칠수 없어 호텔에 들어가자 깨어난 그녀가 재차 나에게 키스. 행위는 점점 더해져, 그녀와 섹스 직전까지 해버렸다. 혹시 사귈 수 있을까…마음속으로 호들갑을 떨며 아침을 맞이했고, 일어난 그녀는 이렇게 말했다 「우와~ 또 저질렀다…」.",
