		"title": "마을에서 젊은 소녀는 나뿐이야 마을 사람을 흥분시키면 ‘누이해 줘야 한다’는 규칙이 있습니다. 그래서 저는 이주한 곳의 아저씨들의 성 처리를 해야 하는 상황이 되었어요. 아오사카 아오이",
		"story": "부모가 이혼하고 어머니의 고향 마을로 이주한 소녀에게 일어나는 이야기. 이 마을에는 오래전부터 전해 내려오는 풍습이 있는데, 딸이 마을 사람을 흥분시키면 반드시 누워야 한다는 규칙이 있다. 그 규칙과 관습, 전설에 휘둘려 남성들의 성 처리를 하게 된 소녀는… 마을 사람들의 선의는 무의식적으로 풍습이라는 힘에 의해 책임이 애매한 채로 액운을 물리치는 성행위가 만연하게 됩니다. 일상의 삶을 지키고, 전통을 이어가며 평화를 유지하기 위해 질내 사정이 정당화되어 가는 것입니다. 소녀와 마을 주민 아저씨들이 펼치는 규칙을 깨는 토착 섹스와 동화 같은 이야기",
