		"story": "나에게는 열 살 이상 나이 차이가 나는 여동생이 있다. 오랜 세월 블랙 기업에 근무해 정신을 앓아 버렸기 때문에 도시에서의 생활을 포기하고 귀향하자, 10년전과 변함없는 가슴 사이즈의 여동생이 상녀 백수가 되어 있었다. 그 시절과 다름없이 나에게 소금 대응 여동생…사실 그녀가 어렸을 때 성적 장난을 치던…팬티를 벗어 신는 걸 보여달라고 관찰하거나, 가슴 보여달라고 해보고, 생각하면 쓰레기인 줄 알았다고 주마등처럼 그 시절을 떠올린다. 하지만 상녀 백수가 된 여동생과 다시 재회하면 원래 작은 노리(炉利)를 좋아하는 나를 부축한다. 그때는 젖꼭지를 만지고도 무반응이었던 여동생. 그런데 오랜만에 젖꼭지를 만지면 감도가 10배로 올라있어! 계속 젖꼭지를 꼬아대서 감도폭상을 시키자 동생이 내 진보를 원해서...",
