		"title": "집이 어디일까?하굣길의 질척질척 사춘기. 임신을 위한 절륜 오지산의 절대적 중출 의무 교육. 마츠모토이치카",
		"story": "하교 중 자전거를 밀고 다니는 소녀.체인 벗어났어?고칠 테니까 와.' 아저씨가 말을 걸어 집으로 올라간다.'다리도 아프겠네' 가는 종아리를 주무르고 무릎 뒤로 핥아라.양말 위에서 발가락 빨기.소리 안 내니까 뭐 해도 돼?젖꼭지 꼬물꼬물 꼬물 꼬물 꼬물 꼬물꼬물.타액과 달콤한 애액이 섞인다.입술을 꽉 조이는 생녀의 미숙한 갈라진 틈에 고기 막대를 삽입.망가질 것 같은 자궁에 귀두가 둥글게. 아름다운 몸을 눌러 찌그러뜨리는 씨를 붙이는 프레스.안으로 꺼내면 백탁액과 처녀혈이 함께 끈적끈적. 그리고 몇번이고 지지이 정자를 받으러 오게 된 츠루페타 양. 대단하네.스스로 페니스를 물고, 촉촉해지는 눈동자로 바라보며 페라. 위에 올라타 어색하게 허리를 흔든다.아, 기분 좋아.임신할 때까지 듬뿍 자멘 따라줄게, 내일도 기다릴게.",
