		"name": "IPZZ-923",
		"title": "죽을 만큼 싫어하는 프로듀서와 촬영지 온천 여관에서 뜻밖의 동거를 하게 되고… 추하고 절정의 아저씨에게 여러 번 절정에 빠진 9머리 키의 미인 모델 탤런트 아스히바 미츠는",
		"story": "특전·세트 상품 정보 오토나의 썸머 캠페인 2026S1과 무디즈, 마돈나 등 인기 제조사의 최신 예약 상품을 포함한 대상 상품이 40% 할인!! ※ 캠페인 종료 후 배송까지 시간이 지연될 경우, 주문을 분할 처리할 수 있습니다. 미리 양해 부탁드립니다. 특전이 포함된 상품·세트 상품에 대하여 인기 모델 출신 연예인 아스히는 TV 활동을 확대하기 위해 여행 프로그램의 온천 촬영에 참여하게 된다. 담당 프로듀서는 쇼와 감성을 끌고 다니는 폭군 같은 사와다. 미츠하는 그를 몹시 싫어했다. 한편, 미츠하는 젊은 매니저와 비밀 연애 중이다. 사내에서도 아주 일부만 알고 있는 비밀 관계다. 하지만 사가와는 그 미묘한 거리감에서 점점 눈치를 채기 시작한다. 촬영 당일, 여관에 도착한 미츠하는 충격을 받는다. 준비된 것은, 뜻밖에도 사가와와의 동거였고. 항의할 틈도 없이 현장의 분위기에 짓눌리는 매니저. 불안을 안고 있으면서도 '설마 아무 일도 일어나지 않을 거야'라고 스스로를 속여버린다. 그날 밤, 사가와는 미츠하를 몰아붙인다. ‘너희들 사귀고 있잖아?’ ‘확증은 없을 텐데, 핵심적인 한마디.’ 이 비밀이 폭로되면 업계에서의 입지는 위태로워진다… 미츠하는 저항할 수 없고, 싫어하던 남자에게 안기면서, 결국 자신도 몰랐던 도M 성향이 드러나기 시작한다…",
