		"story": "'안녕하세요!' 인사하는 모습에서 고급스러움이 묻어나는 여대생. 그녀는 내가 사는 아파트의 동거인. 정숙하고 싱그러운 그녀를 매일 아침 보는 것이 소소한 즐거움이었다. 그러나 어느 날 그녀의 방에서 들려온 것은 너무나 천박한 오호 소리. 그런 바보 같은... 작은 창문으로 어떻게든 방을 들여다보면 빼놓지 않고 정중하게 인사해 주는 그 아이가… 때와는 무관할 것 같은 그 아이가… 투명감 있는 장신 미녀의 그 아이가… 방에 근골융성의 남자를 데리고 들어가, 눈이 부신 이키 미치광이의 ●●●중이었다니…. 최음약에 쫓고 최음약, 섭취가 멈추지 않는 아파트의 한 방…합법적이든 비합법적이든, 하이가 되어, 섹스중에 토하면 된다. 이것이 청초한 그녀의 본성이었던 것이다….",
