		"story": "S1이 자랑하는 장신 여리여리 미녀 '내일잎 미쓰하'가 본격 NTR 드라마 첫 도전!토호쿠에서 상경해 회사원으로 일하는 미쓰하에는, 현지에 같은 세대의 남자친구가 있었다.그러던 중 맞이한 남자 상사와 단둘이 출장.첫 경험으로 순서를 잘못 잡아서 설마 하는 상사와 같은 방에….싫어하는 술을 열심히 사귈 때 술에 취해버려서 상사의 손에 걸리는 꿀은.현지 남자친구의 걱정도 아랑곳하지 않고, 처음 체감하는 남자에게 몸살도 몸살도 물들어가고…특전·세트 상품 정보 연말 신춘 SUPER 캠페인 2023년 12월 19일 아침 10시부터 2024년 1월 22일 아침 10시까지의 기간 동안, S1, 무디스, 마돈나 등 인기 메이커의 최신 예약 상품도 40% 할인! 또한, 구매자를 대상으로 캠페인 걸 엽서(총 20종)를 70000명에게 랜덤으로 1장 증정!※ 캠페인 종료 후, 발송까지 시간이 걸리는 경우, 주문이 분할될 수 있습니다.미리 양해 부탁드립니다.",
