		"story": "【Fitch 전속 여배우·키노시타 히마리와 대인기 동인 서클·미사키의 첫 콜라보!】 “유타의 언니, 정말 예쁘다” 라는 가벼운 농담이었을 텐데, 그 한마디가 모든 것을 뒤흔들기 시작했다. 내게는 몇 안 되는 친구 토시야에게 부탁받아 가볍게 언니 사진을 보여버린 나. 그러다 두 사람은 급속히 가까워지고, ‘연하에게 관심 없을 거라’는 언니가 토시야의 페이스에 휘말리게 된다. 나는 그저 야리친이면서 커뮤니케이션에 강한 친구의 섹스 파트너가 되는 모습을 지켜볼 수밖에 없었다…. 첫 체험 무료 포인트 증정 중!",
