		"title": "지금까지 본 적 없는 천박하고 관능적인 표정에 나도 모르게 우울 발기. 귀성지의 시골에서 재회한 첫사랑의 소꿉친구는, 근처의 아저씨들의 땀이 난 오치 O포를 빨며… 호들갑을 떨고 있었다. 키노시타히마리",
		"story": "혜택, 세트 상품 정보 KMP그룹 대감사 40% 할인 세일!! 6월 30일 아침 10시까지 기간 중 케이엠 프로듀스 그룹 대상 상품이 40% 할인!! ※행사 종료 후, 발송까지 시간이 걸리는 경우, 주문을 분할해 드리는 경우가 있습니다. 미리 양해 부탁드립니다. 혜택이 포함된 상품, 세트 상품에 대해 시골로 귀성한 남자. 좋아하던 소꿉친구 히마리와 오랜만에 재회하고 옛이야기에 꽃을 피우고 있으면 다시 생각이 되살아난다. 그런데 느닷없이 동네 아저씨가 말을 걸어와 히마리는 사라져 간다. 뒤늦게 히마리는 용돈벌이를 위해 아저씨를 상대로 성관계를 하고 있었다. 한 번은 사납게 시들어가는 남자였지만, 지금까지 본 적이 없었던 천박하고 음탕한 마리가 신경 쓰여서…. 『제작·저작 주식회사 케이엠프로듀스 첫회 무료체험 포인트 선물 중!",
