		"story": "혜택, 세트 상품 정보 오토나의 썸머 캠페인 2024 9월 6일 아침 10시까지 기간 중 대상 상품이 40% 할인! 더불어, 대상 상품을 구매하신 분들 중 60000명에게 캠페인걸 엽서(전3종)를 랜덤으로 1장 증정!! ※행사 종료 후, 발송까지 시간이 걸리는 경우, 주문을 분할해 드리는 경우가 있습니다. 미리 양해 부탁드립니다. 혜택이 포함된 상품, 세트 상품에 대해 다정하게 사람 좋은 남편과 불편함 없는 결혼 생활을 하는 리마. 다만 리마에게는 한 가지 불만이 있었다. 그것은 천박하고 델리카시(デリカシーのないで)가 없는 시아버지와의 동거. 성희롱이 다반사인 장인과의 생활에 싫증이 났다. 어느 날 남편이 없는 시간에 잠들어 버린 리마를 발견한 장인어른. 아들이 없는 것을 핑계로, 몰래 속옷을 비우고 암컷과 땀냄새가 섞인 성기를 탐해, 고기봉으로 내미는 가차없는 나카니시레×프. 그리고도 리마는 틈을 보고 덮쳐오는 시아버지에게 젊은 육체를 계속 더럽히고….",
