		"title": "에로비를 빌리러 갔더니, 계산대의 여자아이와 인생이 바뀔 정도로 사랑하고, 약올렸다. 아사노코코로",
		"story": "혜택, 세트 상품 정보 에스원 캠페인 2025 11월 7일 아침 10시부터 12월 12일 아침 10시까지 기간 중, 대상 상품이 30% 할인 & Blu-ray 디스크 온디맨드 상품이 세금 포함 1540엔!! 또한 기간 중에 대상 상품을 구입한 10000명에게는, 에스원 전속 여배우 포스트 카드(전 25종)를 랜덤으로 1매 증정!! ※포스트 카드는 예정 수를 배포하는 대로 종료됩니다. ※행사 종료 후, 발송까지 시간이 걸리는 경우, 주문을 분할해 드리는 경우가 있습니다. 미리 양해 부탁드립니다. 특전부 상품·세트 상품에 대해서 여러분은 인생에서 처음으로 성인 비디오를 빌릴 때의 고양감을 기억하고 있습니까?-처음 R18코너에 발을 들였을 때의 심박수-그녀의 담백한 성행위에 불만이 있는 나는 이력이 들키지 않도록 비디오 가게에서 인생최초의 AV를 렌탈하려고 하고 있었다. 그녀와는 할 수 없는 행위를 몰래 즐기려고 했기 때문이다. 나보다 훨씬 나이 많은 남자 손님들이 모여드는 R-18 코너. 긴장했어. 쑥스럽기도 했다. 나는 볼 생각도 없는 영화도 손에 들고 그 사이에 성인 비디오를 끼웠다. 회계가 가까워지다. 안내받은 계산대의 점원은, 귀여운 미인이었다.(정말이야, 여자야...) 참을 수 없는 부끄러움을 안고, 카운터에 DVD를 올려둔 그 때, 그녀는 나의 눈을 보고, 미소지었다.",
