		"title": "여름의 시골에서는 이런건 보통이야 땀나는 노브라 골짜기에서 무방비로 지내는 소꿉친구 언니에게 욕정해, 모든 것을 잊고 탐닉한 지방 귀성길의 7일간. 쓰바사 마이",
		"story": "대**인 나는 여름방학 일주일정도 시골로 돌아가기로 했어.거기서 오랜만에 만난 근처에 사는 조금 연상의 '마이'.옛날 잘 놀아주던 그녀도 완전히 어른이 되어 탱크톱에서 들여다보는 햇볕에 그을린 피부를 보면 나는 가슴이 철렁 내려앉는다.그 시선을 눈치채고 계곡을 보여주며 유혹하기 시작하는 마이짱.그 육감을 참지 못하고 나는…젖을 비비고, 핥고, 심지어 합체까지….귀성길에 마냥 그 몸을 구걸했던 것이다.특전, 세트 상품 정보 AV 너무 좋아 캠페인 2023년 1월 24일 아침 10시부터 2월 20일 아침 10시까지의 기간 동안, 대상 상품이 최대 35% 할인! 또한 캠페인 기간 동안 대상 상품을 구입하신 분 중 45000명에게 캠페인 걸의 사진(총 9종)을 1장 증정!!※ 캠페인 기간 중이라도 혜택이 소진되는 대로 본 표시와 상관없이 배포는 종료됩니다.※개별 주문에 대한 혜택 부여에 대한 문의에는 대답할 수 없으므로 미리 양해 바랍니다.",
