		"story": "남편의 이직으로 장인어른과 함께 살게 된 지 몇 달.나는 이 장인어른을 좋아할 수 없어.매일매일의 성희롱 사건들 빨리 이 집을 떠나고 싶습니다.」무의 예감이 맞은 것은, 그로부터 얼마 지나지 않았다.장인에게 약점을 잡힌 춤은 남편 부재의 낮…싫어하는 시아버지의 육봉을 자신의 꿀단지로 받아들일 수밖에 없었다.그날부터 그녀의 몸뚱이는 장인의 성욕구가 되고, 그리고 그녀는 욕심 많은 육봉을 잊을 수 없게 된다.특전 및 세트 상품 정보 S1 캠페인 2023 5월 16일 아침 10시부터 6월 19일 아침 10시까지의 기간 동안, S1 대상 상품이 30% 할인! 또한 기간 중 대상 상품을 구입하신 7200명에게 캠페인 걸의 생사진(총 30종)을 랜덤으로 1장 증정! 그 중 행운아인 1940명에게는 팬트라에서 사용할 수 있는 카와키타 아야카 씨의 트럼프도 1장 증정!!※ 캠페인 종료 후, 발송까지 시간이 걸리는 경우, 주문이 분할될 수 있습니다.미리 양해 부탁드립니다.",
