		"story": "혜택, 세트 상품 정보 SOD 그룹 40%OFF 세일 7월 1일 아침 10시부터 7월 31일 아침 10시까지의 기간 동안 SOD 크리에이트와 FALENO, 내츄럴 하이 외, SOD 그룹 대상 상품이 40% 할인!! ※행사 종료 후, 발송까지 시간이 걸리는 경우, 주문을 분할해 드리는 경우가 있습니다. 미리 양해 부탁드립니다. 혜택이 포함된 상품, 세트 상품에 대해 옛날부터 좋아했던 소꿉친구가 풍속녀가 된... 그런 소문을 듣고 나서 첫 연락. '오늘부터 좀 묵게 해줘' 나는 복잡한 감정을 가진 채 마이짱과의 동거 생활이 시작됐다. 아빠, 핀살로, 소프, 실전 행위, 온갖 테크닉으로 나는 소꿉친구에게 계속 눌렸다. 행복했던 3일간이 시작되고 끝났다.",
