		"story": "[흘러나올것같은 젖가슴...거의 보이는 엉덩이...참을수있을까...! 이런 거...! 예로부터 숙모는 대담했다…. 수능 때문에 이모집에 신세를 지게 된 나. 깨끗한 신체를 유지하기 위해 이모가 평소 하던 근육 트레이닝을 시작했을 때 눈을 의심했다. 뭐야 이 옷은...아니 이건 옷인가...이제 거의 다 보여...참지 못하고 바로 해버렸다. 격렬한 피스톤으로 흔들리는 거유, 큰 엉덩이, 그리고 조여오는 질내. 금방 끝나버린 나였지만, 숙모는 아직 부족한 눈을 하고 있다. 거기에서 시간을 가리지 않고 유혹되어 숙모의 성처리 도구로서 질조임 섹스를 몇번이나 몇번이나 몇번이나 했다.",
