		"story": "결혼해 아버지가 사는 친정에서 셋이 살기 시작한 나와 수이는 폴리네시안 섹스를 해보기로 했다.폴리네시안 섹스란 4일간은 차분히 애무만 하고 5일째 섹스할 때도 전희에 시간을 들이고 삽입 후에도 한동안 움직이지 않고 기분을 높임으로써 절정이 깊고 오래가는 섹스라고 한다.삽입할 날을 기대하고 있던 나와 수이였지만, 그 5일째에 급거 차마 거절할 수 없는 출장이 들어가 버린다.웅크리고 있는 몸을 주체하지 못하고 침실에서 안내하는 것.그것을 목격하고 이성을 잃는 아버지.4일간 성감을 높이는 만큼 높아진 따끈따끈 따끈 따끈한 ○ 이것이, 절륜 부모의 끈적한 피스톤에 차분히 휘저어진다.그리고, 웅덩이에 쌓인 욕구가 터지는 폭발적인 바닷바람 절정에서, 쾌락의 가치관을 고쳐 쓴 제비는…….",
