		"story": "하기강습으로 부모님 곁을 떠나 도쿄에서 자취를 2주간 하게 된 수제비. 이모가 소유한 아파트 방을 빌렸는데, 살기 시작하자마자 옆방에서 풍기는 예사롭지 않은 냄새를 알게 된다. 방 밖에까지 쏟아져 나오는 많은 양의 쓰레기를 본 수이는 이웃집에 하소연을 하러 간다. 계집애의 클레임에 흥분한 중년 아저씨는 쓰레기방에 억지로 끌고 들어가 덤벼든다. 그리고 산란하는 더러워진 쓰레기 속에서 능가●되어 몇 발이나 중출되어…. 이상성욕한 불결아재의 절륜생하메로 범●계속되는 미소녀. 「이제 엄마●아이가 정자로 빵빵해요」빼지 않는 연격중출 38발! 목줄을 매고 손을 잡고… 육변기에 걸린 수제비는 이제 이 쓰레기방을 벗어날 수 없다.",
