		"story": "특전·세트 상품 정보 여름 BIG 세일은 7월 28일 오전 10시부터 8월 28일 오전 10시까지 진행되며, 해당 상품이 40% 할인! ※ 캠페인 종료 후 배송까지 시간이 지연될 경우, 주문을 분할 처리할 수 있습니다. 미리 양해 부탁드립니다. 특전이 포함된 상품·세트 상품에 대하여 회사 승진 심사에서 좋은 평가를 받아 기분이 좋았던 남편은, 귀가 길에 역 앞 술집에서 혼자 건배를 올리고 있었다. 그곳에서 옆에 있던 중년 남성과 뜻이 맞은 남편은, 그 ‘이케누마’라는 남자를 데리고 집에서 다시 술을 마시기로 했다. 갑작스러운 손님에 약간 당황하면서도 술과 안주를 준비하는 아내. 기분 좋게 마시는 남편은 몰랐다. 그 손님인 이케누마는 연속 여성 폭행죄로 복역을 마치고 얼마 전 막 출소한, 압도적인 발기력을 가진 야수 같은 거대한 성기 수감자였다…",
