		"story": "신입사원 안달이 함께 출장을 가게 된 것은 평소 성희롱 기질로 매우 싫어하는 상사의 사사로운 산.선배 요시다와 사내 교제를 하고 있던 야스다치는 불만을 털어놓아도 달래지는 형태로 마지못해 출장을 갔다.출장지에서 사사로이 산을 반주로 사귄 안달은 수면제를 담그고 눈을 뜨면 자신의 몸을 탐하고 있는 사사로이 산이 눈앞에…처음에는 저항했지만 지○포를 꽂히는 순간 온몸을 휘젓는 쾌감.신체 궁합이 최고로 발군해서 밤새 계속 생기더라고요.특전 및 세트 상품 정보 S1 캠페인 2023 5월 16일 아침 10시부터 6월 19일 아침 10시까지의 기간 동안, S1 대상 상품이 30% 할인! 또한 기간 중 대상 상품을 구입하신 7200명에게 캠페인 걸의 생사진(총 30종)을 랜덤으로 1장 증정! 그 중 행운아인 1940명에게는 팬트라에서 사용할 수 있는 카와키타 아야카 씨의 트럼프도 1장 증정!!※ 캠페인 종료 후, 발송까지 시간이 걸리는 경우, 주문이 분할될 수 있습니다.미리 양해 부탁드립니다.",
